use regular::*;
fn http()->reqwest::Client{let mut headers=reqwest::header::HeaderMap::new();headers.insert(reqwest::header::AUTHORIZATION,reqwest::header::HeaderValue::from_static("Bearer secret"));reqwest::Client::builder().default_headers(headers).build().unwrap()}
fn codecs()->GraphqlScalarCodecs{GraphqlScalarCodecs::new().with::<String,i64>("DateTime",|value|Ok(serde_json::Value::String(format!("wire-{value}"))),|value|value.as_str().and_then(|v|v.strip_prefix("wire-")).ok_or("invalid wire scalar".to_string())?.parse::<i64>().map_err(|e|e.to_string()))}
fn success<T>(value:GraphqlResponse<T>)->T{match value{GraphqlResponse::Success{data,..}=>data,_=>panic!("expected success")}}
#[tokio::main]async fn main(){
 let endpoint=std::env::var("GRAPHQL_ENDPOINT").unwrap();let transport=GraphqlHttpTransport::new(&endpoint,http()).with_codecs(codecs());let client=Client::from_transport(transport.clone());
 let variables=ReadVariables{input:Filter{when:"7".into(),list:Presence::Value(vec![None,Some("9".into())]),next:Presence::Value(Box::new(Filter{when:"8".into(),list:Presence::Absent,next:Presence::Absent}))},include:false};
 let result=success(client.read(&variables).await.unwrap());assert_eq!(result.stamp.when,7);assert_eq!(result.stamp.list,Some(vec![None,Some(9)]));assert!(matches!(result.stamp.maybe,Presence::Absent));assert_eq!(variables.input.when,"7");
 let mut stream=client.ticks(&TicksVariables{start:"7".into()}).await.unwrap();let first=success(stream.next().await.unwrap().unwrap());assert_eq!(first.ticks.when,7);assert_eq!(first.ticks.name,"é");assert!(matches!(stream.next().await.unwrap(),Some(GraphqlResponse::Partial{..})));assert!(stream.next().await.unwrap().is_none());
 let mut cancelled=client.ticks(&TicksVariables{start:"99".into()}).await.unwrap();assert!(cancelled.next().await.unwrap().is_some());drop(cancelled);tokio::time::sleep(std::time::Duration::from_millis(100)).await;let closed:serde_json::Value=http().get(format!("{endpoint}/closed")).send().await.unwrap().json().await.unwrap();assert!(closed["closed"].as_u64().unwrap()>=2);
 for suffix in ["sse-split","sse-eof","sse-bad"]{let transport=GraphqlHttpTransport::new(format!("{endpoint}/{suffix}"),http()).with_codecs(codecs());let mut stream=ticks(&transport,&TicksVariables{start:"7".into()}).await.unwrap();if suffix=="sse-split"{assert_eq!(success(stream.next().await.unwrap().unwrap()).ticks.name,"é");assert!(stream.next().await.unwrap().is_none());}else if suffix=="sse-eof"{assert!(stream.next().await.unwrap().is_some());assert!(stream.next().await.is_err());}else{assert!(stream.next().await.is_err());}}
 let encode_error=GraphqlScalarCodecs::new().with::<String,i64>("DateTime",|_|Err("encode rejected".into()),|_|Ok(7));let bad=Client::from_transport(GraphqlHttpTransport::new(&endpoint,http()).with_codecs(encode_error));assert!(matches!(bad.read(&variables).await,Err(GraphqlTransportError::Protocol(_))));
 let decode_error=GraphqlScalarCodecs::new().with::<String,i64>("DateTime",|value|Ok(serde_json::Value::String(format!("wire-{value}"))),|_|Err("decode rejected".into()));let bad=Client::from_transport(GraphqlHttpTransport::new(&endpoint,http()).with_codecs(decode_error));assert!(matches!(bad.read(&variables).await,Err(GraphqlTransportError::Protocol(_))));
 for suffix in ["","/plain","/invalid-path","/eof","/dialect"]{
   let transport=incremental::GraphqlHttpTransport::new(format!("{endpoint}{suffix}"),http()).with_codecs(incremental::GraphqlScalarCodecs::new().with::<String,i64>("DateTime",|value|Ok(serde_json::Value::String(format!("wire-{value}"))),|value|value.as_str().and_then(|v|v.strip_prefix("wire-")).unwrap().parse::<i64>().map_err(|e|e.to_string())));
   let client=incremental::Client::from_transport(transport);let mut stream=client.feed(&incremental::FeedVariables{count:1}).await.unwrap();let mut complete=false;let mut failure=false;let mut snapshots=0;
   loop{match stream.next().await{Ok(Some(incremental::GraphqlIncrementalEvent::Snapshot(value)))=>{snapshots+=1;if suffix.is_empty()&&snapshots==1{assert!(value.data.unwrap()["user"].get("when").is_none());}},Ok(Some(incremental::GraphqlIncrementalEvent::Complete(incremental::GraphqlResponse::Success{data,..})))=>{assert_eq!(data.user.when,7);assert_eq!(data.values,vec![1,2,3]);complete=true;},Ok(None)=>break,Err(incremental::GraphqlTransportError::Protocol(_))=>{failure=true;break},other=>panic!("unexpected incremental state: {}",match other{Err(e)=>e.to_string(),_=>"non-success".into()})}}
   if suffix==""||suffix=="/plain"{assert!(complete&&!failure);}else{assert!(failure&&!complete);}
 }
}
